import rawTownsData from "@/data/map-pois/towns.json";
import type { MapPoi } from "./map-layers";

// Thin continent-filtering reader over data/map-pois/towns.json (generated by
// scripts/build-towns.js from the client's AreaPOI table) onto the generic
// MapPoi shape. AreaPOI has no faction column, so towns get the neutral pin.

type RawTown = {
  id: string;
  name: string;
  kind: string;
  continent: string;
  worldPosition: { x: number; y: number };
  source: string;
};

const allTowns = rawTownsData.towns as RawTown[];

export function getTownPois(continentId: string): MapPoi[] {
  return allTowns
    .filter((t) => t.continent === continentId)
    .map((t) => ({
      id: t.id,
      layer: "towns",
      name: t.name,
      kindLabel: t.kind,
      faction: null,
      worldPosition: t.worldPosition,
      source: t.source,
    }));
}
